try {
  // 1. ДАННЫЕ ИЗ БАЗЫ (Результат SQL-запроса)
  const dbContext = $input.first() ? $input.first().json : null; 

  // 🌟 МАГИЯ ВОССТАНОВЛЕНИЯ ТЕКСТА ИЗ ПЕРВОИСТОЧНИКА 🌟
  let realRawText = "";
  let sourceChannel = "telegram";
  let senderId = "unknown";

  const allStartItems = $('Input Normalizer').all();
  if (allStartItems && allStartItems.length > 0) {
      // Ищем тот самый вебхук, в котором был текст (игнорируя пустые фото и "null")
      for (const item of allStartItems) {
          const text = item.json.raw_text;
          if (text && String(text).toLowerCase() !== "null" && String(text).trim() !== "") {
              realRawText = item.json.raw_text;
          }
      }
      // Берем базовые данные
      sourceChannel = allStartItems[0].json.channel || "telegram";
      senderId = allStartItems[0].json.sender_id || "unknown";
  }

  // 2. ДАННЫЕ С ФОТОГРАФИЯМИ
  let filesBase64 = [];
  let hasAttachments = false;
  const aggregateNode = $('Code: Aggregate Album');

  if (aggregateNode && aggregateNode.isExecuted) {
      // Если это альбом — берем склеенные фотки
      const aggData = aggregateNode.first().json;
      filesBase64 = aggData.files_base64 || [];
      hasAttachments = true;
  } else {
      // Обычное сообщение
      if (allStartItems && allStartItems.length > 0) {
          filesBase64 = allStartItems[0].json.files_base64 || [];
          hasAttachments = filesBase64.length > 0;
      }
  }

  // 3. ЛОГИКА МАРШРУТИЗАЦИИ
  let targetWorker = "worker_sdr"; // По умолчанию - продажи
  let isKnown = false;

  if (dbContext && dbContext.user_type) {
    isKnown = true;
    if (dbContext.user_type === "employee") {
      targetWorker = "worker_internal_ops";
    } else if (dbContext.user_type === "client") {
      const clientStatus = dbContext.client_status;

      // 🌟 ИСПРАВЛЕНИЕ: Разделили зоны ответственности (Separation of Concerns)
      const salesStages = ["lead", "onboarding_start", "active_sales"]; 
      const supportStages = ["implementation", "active"];

      if (salesStages.includes(clientStatus)) {
          targetWorker = "worker_sdr";
      } else if (supportStages.includes(clientStatus)) {
          targetWorker = "worker_support"; // Внедрение и поддержка идут к технарям!
      } else {
          // Fallback-предохранитель
          targetWorker = dbContext.active_ticket_id ? "worker_support" : "worker_sdr";
      }
    }
  }

  // 4. СБОРКА ENTERPRISE-КОНТРАКТА
  const payload = {
    metadata: {
      event_id: `req_${Math.random().toString(36).substr(2, 9)}`,
      timestamp: new Date().toISOString(),
      source_channel: sourceChannel, 
      target_worker: targetWorker
    },
    sender: {
      contact_id: senderId,
      user_type: isKnown ? dbContext.user_type : "unknown",
      name: isKnown ? dbContext.name : "Unknown",
      role_or_niche: isKnown ? dbContext.role_or_niche : null
    },
    payload: {
      raw_text: realRawText,
      clean_text: realRawText ? realRawText.trim() : "",
      has_attachments: hasAttachments,
      files_base64: filesBase64 
    },
    context: {
      crm_deal_id: isKnown ? dbContext.crm_deal_id : null,
      client_status: isKnown ? dbContext.client_status : null,
      dify_conversation_id: isKnown ? dbContext.dify_conversation_id : null,
      active_ticket_id: isKnown ? dbContext.active_ticket_id : null,
      is_awaiting_approval: false 
    }
  };

  // 5. ВЫДАЧА
  return [{ json: payload }];

} catch (error) {
  throw new Error(`[Payload Builder Error]: Ошибка сборки контракта. Причина: ${error.message}`);
}

