try {
    const dbItems = $input.all();
    if (dbItems.length === 0) return [];

    const originalData = $('Input Normalizer').first().json;

    let finalRawText = "";
    let allFiles = [];

    for (const item of dbItems) {
        const row = item.json;

        if (row.caption && row.caption.trim() !== "") {
            finalRawText = row.caption;
        }

        if (row.base64_data) {
            try {
                // Разбираем строку из БД
                const parsedFiles = JSON.parse(row.base64_data);

                // ГАРАНТИЯ ПЛОСКОГО МАССИВА: Если это массив, добавляем его элементы
                if (Array.isArray(parsedFiles)) {
                    allFiles.push(...parsedFiles); 
                } else if (typeof parsedFiles === 'object') {
                    // Если это просто один объект, добавляем его
                    allFiles.push(parsedFiles);
                }
            } catch (e) {
                // Игнорируем битый JSON
            }
        }
    }

    return [{
        json: {
            sender_id: originalData.sender_id,
            channel: originalData.channel,
            raw_text: finalRawText,
            media_group_id: originalData.media_group_id,
            files_base64: allFiles, // Теперь тут идеально ровный список объектов
            has_attachments: true
        }
    }];

} catch (error) {
    throw new Error(`[Album Aggregator Error]: ${error.message}`);
}

try {
    const items = $input.all();
    const results = [];

    for (let i = 0; i < items.length; i++) {
        const item = items[i];
        const json = item.json || {};
        const webhookData = json.body || json; // Иногда вебхук прячет данные в body

        // 1. OMNI-CHANNEL NORMALIZATION (УНИВЕРСАЛЬНЫЙ ПАРСЕР)
        let senderId = "unknown";
        let channel = "unknown";
        let rawText = "";
        let mediaGroupId = null; 

        // 🔵 СЦЕНАРИЙ А: TELEGRAM
        if (webhookData.message && webhookData.message.chat) {
            senderId = String(webhookData.message.chat.id);
            channel = "telegram";
            rawText = webhookData.message.text || webhookData.message.caption || "";

            if (webhookData.message.media_group_id) {
                mediaGroupId = String(webhookData.message.media_group_id);
            }
        } 
        // 🔴 СЦЕНАРИЙ Б: EMAIL (Gmail / IMAP Trigger)
        else if (webhookData.from && webhookData.from.value && Array.isArray(webhookData.from.value)) {
            // Вытаскиваем email из массива (например: babardinio@proton.me)
            senderId = String(webhookData.from.value[0].address);
            channel = "email";

            // Вытаскиваем текст письма
            rawText = webhookData.text || webhookData.textPlain || webhookData.snippet || "";

            // Микро-клининг: отрезаем стандартные подписи почтовиков
            if (rawText.includes("Sent with Proton Mail")) {
                rawText = rawText.split("Sent with Proton Mail")[0].trim();
            }

            // 🛑 НОВАЯ ВСТАВКА: ОЧИСТКА ОТ ИСТОРИИ ПЕРЕПИСКИ (ЗАГРЯЗНЕНИЯ КОНТЕКСТА)
            // Обрезаем всё, что начинается с "\n\n" и дня недели (формат Gmail) или знака цитаты ">"
            rawText = rawText.split(/\n\n(?=(?:пн|вт|ср|чт|пт|сб|вс|On|Mon|Tue|Wed|Thu|Fri|Sat|Sun))/i)[0];
            rawText = rawText.split(/(?:\n>|\n >)/)[0].trim();
        } 
        // 🟣 СЦЕНАРИЙ В: Внутренний API / Кастомный формат
        else if (webhookData.sender && webhookData.sender.contact_id) {
            senderId = String(webhookData.sender.contact_id);
            channel = webhookData.metadata?.source_channel || "api";
            rawText = webhookData.payload?.raw_text || "";
        }

        // 2. БРОНЕБОЙНОЕ ИЗВЛЕЧЕНИЕ ФАЙЛА (Dual Fallback)
        let encodedFiles = [];

        if (item.binary) {
            const keys = Object.keys(item.binary);
            for (const key of keys) {
                const binData = item.binary[key];
                if (!binData) continue;

                let base64String = "";

                // ПОПЫТКА 1: Официальный API n8n
                if (this.helpers && typeof this.helpers.getBinaryDataBuffer === 'function') {
                    try {
                        const buffer = await this.helpers.getBinaryDataBuffer(i, key);
                        if (buffer) {
                            base64String = buffer.toString('base64');
                        }
                    } catch (err) {}
                }

                // ПОПЫТКА 2: Прямое чтение
                if (!base64String && binData.data) {
                    base64String = binData.data;
                }

                // Сохраняем файл
                if (base64String) {
                    if (base64String.includes('base64,')) {
                        base64String = base64String.split('base64,')[1];
                    }

                    encodedFiles.push({
                        mime_type: binData.mimeType || "application/octet-stream",
                        file_name: binData.fileName || `file_${key}`,
                        base64: base64String
                    });
                }
            }
        }

        // 3. ОТДАЕМ ИДЕАЛЬНЫЙ СТАНДАРТИЗИРОВАННЫЙ РЕЗУЛЬТАТ
        results.push({
            json: {
                sender_id: senderId,
                channel: channel,
                raw_text: rawText,
                media_group_id: mediaGroupId,
                files_base64: encodedFiles
            }
        });
    }

    return results;

} catch (error) {
    const errorDetails = error && error.message ? error.message : String(error);
    throw new Error(`[Input Normalizer Error]: Сбой парсинга. Детали: ${errorDetails}`);
}

